import json
data = json.loads(context)
best = {}
for row in data:
    key = (row['record_date'], row['src_line_nbr'])
    ver = row['version']
    if key not in best or ver > best[key]['version']:
        best[key] = row
deposits = 0
withdrawals = 0
for row in best.values():
    at = row['account_type']
    amount = int(row['open_today_bal'])
    if at == 'Total TGA Deposits (Table II)':
        deposits += amount
    elif at == 'Total TGA Withdrawals (Table II) (-)':
        withdrawals += amount
result = deposits - withdrawals
print(FINAL(str(result)))
